Q: How to do try catch and finally statements in TypeScript? A: <p>What works in my case is like this.
To print to terminal:</p>
<pre><code>catch(error){
  log('any_text', error as Error);
}
</code></pre>
<p>or call metod:</p>
<pre><code>catch(error){
   anything_here((error as Error).message),
}
</code></pre>

Q: How to add custom transitions to my Flutter route in my Flutter app A: <p>A better way is to create a RouteGenerator class with string values for named routes.  This way you reference all your routes from one class.  The RouteGenerator class contains one method:  static Route&lt;dynamic&gt; handleRoute(RouteSettings routeSettings) with case statements for each MaterialPageRoute.</p>
<p>A switch statement matches the string to a route and the MaterialPageRoute pushes the widget on the stack.  you can also get access to arguments passed to the Route Generator</p>
<p>in main.dart</p>
<pre><code>  onGenerateRoute: RouteGenerator.handleRoute,
</code></pre>
<p>navigation from a childwidget</p>
<pre><code>  Navigator.pushNamed(context, RouteGenerator.page1Page,
                                arguments: myCustomView)
</code></pre>
<p>Class</p>
<pre><code> class RouteGenerator {
  static const String homePage = &quot;/home&quot;;
  static const String page1Page = &quot;/page1&quot;;
  static const String page2Page = &quot;/page2&quot;;

  RouteGenerator._();
  static Route&lt;dynamic&gt; handleRoute(RouteSettings routeSettings) {
   Widget childWidget;
   switch (routeSettings.name) {
    case homePage:
    {
      childWidget = HomePageWidget(title: 'abc');
    }
    break;
  case page1Page:
    {
      childWidget = Page1Widget();
    }
    break;
  case page2Page:
    {
      final args = routeSettings.arguments as MyCustomView;
      childWidget = Page2Widget(args);
    }
    break;
  default:
    throw FormatException(&quot;Route Not Found&quot;);
  }
  return MaterialPageRoute(builder: (context) =&gt; childWidget);
 }
 }
</code></pre>

Q: Using std::hash with variant replacement on C++14 A: <p>Use the inline <code>apply_visitor</code> approach unless you specifically need <code>std::hash&lt;variant&gt;</code> for unordered containers. Define a custom <code>std::hash</code> specialization for <code>mapbox::util::variant</code>:</p>
<pre class="lang-cpp prettyprint-override"><code>#include &lt;mapbox/variant.hpp&gt;
#include &lt;functional&gt;
#include &lt;string&gt;

namespace std {
    template &lt;&gt;
    struct hash&lt;mapbox::util::variant&lt;std::string, int64_t, double, bool&gt;&gt; {
        std::size_t operator()(mapbox::util::variant&lt;std::string, int64_t, double, bool&gt; const&amp; v) const noexcept {
            return mapbox::util::apply_visitor([](auto const&amp; val) {
                return std::hash&lt;typename std::decay&lt;decltype(val)&gt;::type&gt;{}(val);
            }, v);
        }
    };
}

std::size_t operator()(const OpenXLSX::XLCellValue&amp; value) const noexcept {
    return std::hash&lt;mapbox::util::variant&lt;std::string, int64_t, double, bool&gt;&gt;{}(value.m_value);
}
</code></pre>
